// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherCartel c;

    function setUp() public {
        c = new EtherCartel();
    }

    function _run(address caller) internal {
        vm.assume(caller != address(0));
        bool reverted;
        address currentCeo;
        try c.ceoAddress() returns (address __r) { currentCeo = __r; } catch { return; }
        try c.DrugDealer() { reverted = false; } catch { reverted = true; }
        assertTrue((currentCeo == address(this) && reverted == false) || (currentCeo != address(this) && reverted == true));
    }

    function testFuzz_run(address caller) public {
        _run(caller);
    }

    receive() external payable {}
}
